insert into CHB_INVESTHOLD_TMP( REGIST_BANK_CODE, INDENTIFY_MARK, MERGER_INDENTIFY_MARK,PRD_REGIST_CODE,HOLD_DATE, CCY, AMOUNT, QTY, CNY_AMT, REMARK, DATA_SOURCE,STATUS,OPERATE_STATUS, WORKFLOW_ID, ORG_CODE, DEPT_CODE, AGENT,PRODID,INTERF_CHECK_RESULT, AGENCY_CODE,FUND_ACC_PLACE, CREATE_DEPT, UPDATE_USER, UPDATE_TIME,CREATE_USER,CREATE_TIME,FILE_NAME,DATA_ROW_NO) select REGIST_BANK_CODE, INDENTIFY_MARK, MERGER_INDENTIFY_MARK,PRD_REGIST_CODE,HOLD_DATE, CCY, AMOUNT, QTY, CNY_AMT, REMARK, DATA_SOURCE,STATUS,OPERATE_STATUS, WORKFLOW_ID, ORG_CODE, DEPT_CODE, AGENT,PRODID,INTERF_CHECK_RESULT, AGENCY_CODE,FUND_ACC_PLACE, CREATE_DEPT, UPDATE_USER, UPDATE_TIME,CREATE_USER,CREATE_TIME,FILE_NAME,DATA_ROW_NO from ( select TEMP.* from (
select #{item.registBankCode,jdbcType=VARCHAR} REGIST_BANK_CODE, #{item.indentifyMark,jdbcType=VARCHAR} INDENTIFY_MARK, #{item.mergerIndentifyMark,jdbcType=VARCHAR} MERGER_INDENTIFY_MARK, #{item.prdRegistCode,jdbcType=VARCHAR} PRD_REGIST_CODE, #{item.holdDate,jdbcType=DATE} HOLD_DATE, #{item.ccy,jdbcType=VARCHAR} CCY, convert(#{item.amount},DECIMAL(15,2)) AMOUNT, convert(#{item.qty},DECIMAL(18,5)) QTY, convert(#{item.cnyAmt},DECIMAL(15,2)) CNY_AMT, #{item.remark,jdbcType=VARCHAR} REMARK, #{item.dataSource,jdbcType=VARCHAR} DATA_SOURCE, #{item.status,jdbcType=VARCHAR} STATUS, #{item.operateStatus,jdbcType=VARCHAR} OPERATE_STATUS, #{item.workflowId,jdbcType=VARCHAR} WORKFLOW_ID, #{item.orgCode,jdbcType=VARCHAR} ORG_CODE, #{item.deptCode,jdbcType=VARCHAR} DEPT_CODE, #{item.agent,jdbcType=VARCHAR} AGENT, #{item.prodid,jdbcType=VARCHAR} PRODID, #{item.interfCheckResult,jdbcType=VARCHAR} INTERF_CHECK_RESULT, #{item.agencyCode,jdbcType=VARCHAR} AGENCY_CODE, #{item.fundAccPlace,jdbcType=VARCHAR} FUND_ACC_PLACE, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=DATE} UPDATE_TIME, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createTime,jdbcType=DATE} CREATE_TIME, #{item.fileName,jdbcType=VARCHAR} FILE_NAME, #{item.dataRowNo,jdbcType=VARCHAR} DATA_ROW_NO from dual
) TEMP where not EXISTS (select 1 from CHB_INVESTHOLD_TMP CII where CII.REGIST_BANK_CODE = TEMP.REGIST_BANK_CODE and CII.INDENTIFY_MARK = TEMP.INDENTIFY_MARK and CII.PRODID = TEMP.PRODID and CII.CCY = TEMP.CCY and CII.HOLD_DATE = TEMP.HOLD_DATE and CII.AGENCY_CODE = TEMP.AGENCY_CODE and CII.FUND_ACC_PLACE = TEMP.FUND_ACC_PLACE) ) de ;
UPDATE CHB_INVESTHOLD_TMP as A, ( select REGIST_BANK_CODE, INDENTIFY_MARK, MERGER_INDENTIFY_MARK,PRD_REGIST_CODE,HOLD_DATE, CCY, AMOUNT, QTY, CNY_AMT, REMARK, DATA_SOURCE,STATUS,OPERATE_STATUS, WORKFLOW_ID, ORG_CODE, DEPT_CODE, AGENT,PRODID,INTERF_CHECK_RESULT, AGENCY_CODE,FUND_ACC_PLACE, CREATE_DEPT, UPDATE_USER, UPDATE_TIME,CREATE_USER,CREATE_TIME,FILE_NAME,DATA_ROW_NO from ( select TEMP.* from (
select #{item.registBankCode,jdbcType=VARCHAR} REGIST_BANK_CODE, #{item.indentifyMark,jdbcType=VARCHAR} INDENTIFY_MARK, #{item.mergerIndentifyMark,jdbcType=VARCHAR} MERGER_INDENTIFY_MARK, #{item.prdRegistCode,jdbcType=VARCHAR} PRD_REGIST_CODE, #{item.holdDate,jdbcType=DATE} HOLD_DATE, #{item.ccy,jdbcType=VARCHAR} CCY, convert(#{item.amount},DECIMAL(15,2)) AMOUNT, convert(#{item.qty},DECIMAL(18,5)) QTY, convert(#{item.cnyAmt},DECIMAL(15,2)) CNY_AMT, #{item.remark,jdbcType=VARCHAR} REMARK, #{item.dataSource,jdbcType=VARCHAR} DATA_SOURCE, #{item.status,jdbcType=VARCHAR} STATUS, #{item.operateStatus,jdbcType=VARCHAR} OPERATE_STATUS, #{item.workflowId,jdbcType=VARCHAR} WORKFLOW_ID, #{item.orgCode,jdbcType=VARCHAR} ORG_CODE, #{item.deptCode,jdbcType=VARCHAR} DEPT_CODE, #{item.agent,jdbcType=VARCHAR} AGENT, #{item.prodid,jdbcType=VARCHAR} PRODID, #{item.interfCheckResult,jdbcType=VARCHAR} INTERF_CHECK_RESULT, #{item.agencyCode,jdbcType=VARCHAR} AGENCY_CODE, #{item.fundAccPlace,jdbcType=VARCHAR} FUND_ACC_PLACE, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, now() UPDATE_TIME, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createTime,jdbcType=VARCHAR} CREATE_TIME, #{item.fileName,jdbcType=VARCHAR} FILE_NAME, #{item.dataRowNo,jdbcType=VARCHAR} DATA_ROW_NO from dual
) TEMP ) de ) AS B SET A.MERGER_INDENTIFY_MARK = B.MERGER_INDENTIFY_MARK ,A.AMOUNT = B.AMOUNT ,A.PRD_REGIST_CODE = B.PRD_REGIST_CODE ,A.QTY = B.QTY ,A.CNY_AMT = B.CNY_AMT ,A.REMARK = B.REMARK ,A.DATA_SOURCE = B.DATA_SOURCE ,A.STATUS = B.STATUS ,A.OPERATE_STATUS = B.OPERATE_STATUS ,A.WORKFLOW_ID = B.WORKFLOW_ID ,A.ORG_CODE = B.ORG_CODE ,A.DEPT_CODE = B.DEPT_CODE ,A.ORG_CODE = B.ORG_CODE ,A.AGENT = B.AGENT ,A.INTERF_CHECK_RESULT = B.INTERF_CHECK_RESULT ,A.UPDATE_USER = B.UPDATE_USER ,A.UPDATE_TIME = B.UPDATE_TIME ,A.FILE_NAME = B.FILE_NAME ,A.DATA_ROW_NO = B.DATA_ROW_NO where A.REGIST_BANK_CODE = B.REGIST_BANK_CODE and A.INDENTIFY_MARK = B.INDENTIFY_MARK and A.PRODID = B.PRODID and A.CCY = B.CCY and A.HOLD_DATE = B.HOLD_DATE and A.AGENCY_CODE = B.AGENCY_CODE and A.FUND_ACC_PLACE = B.FUND_ACC_PLACE;

insert into chb_investhold_info_check( REGIST_BANK_CODE,INDENTIFY_MARK,PRD_REGIST_CODE,HOLD_DATE, CCY,AMOUNT,QTY,CNY_AMT,REMARK,DATA_SOURCE,STATUS,OPERATE_STATUS,WORKFLOW_ID, ORG_CODE,DEPT_CODE,UPDATE_USER,UPDATE_TIME,CREATE_USER,CREATE_TIME,AGENT,CREATE_DEPT, PRODID,INTERF_CHECK_RESULT,XBRL_BACK_RESULT,AGENCY_CODE,FUND_ACC_PLACE ) select REGIST_BANK_CODE,INDENTIFY_MARK,PRD_REGIST_CODE,HOLD_DATE, CCY,AMOUNT,QTY,CNY_AMT,REMARK,DATA_SOURCE,STATUS,OPERATE_STATUS,WORKFLOW_ID, ORG_CODE,DEPT_CODE,UPDATE_USER,UPDATE_TIME,CREATE_USER,CREATE_TIME,AGENT,CREATE_DEPT, PRODID,INTERF_CHECK_RESULT,XBRL_BACK_RESULT,AGENCY_CODE,FUND_ACC_PLACE from ( select TEMP.* from (
SELECT #{item.registBankCode,jdbcType=VARCHAR} REGIST_BANK_CODE, #{item.indentifyMark,jdbcType=VARCHAR} INDENTIFY_MARK, #{item.prdRegistCode,jdbcType=VARCHAR} PRD_REGIST_CODE, #{item.holdDate,jdbcType=DATE} HOLD_DATE, #{item.ccy,jdbcType=VARCHAR} CCY, #{item.amount,jdbcType=DECIMAL} AMOUNT, #{item.qty,jdbcType=DECIMAL} QTY, #{item.cnyAmt,jdbcType=DECIMAL} CNY_AMT, #{item.remark,jdbcType=VARCHAR} REMARK, #{item.dataSource,jdbcType=VARCHAR} DATA_SOURCE, #{item.status,jdbcType=VARCHAR} STATUS, #{item.operatestatus,jdbcType=VARCHAR} OPERATE_STATUS, #{item.workflowId,jdbcType=VARCHAR} WORKFLOW_ID, #{item.orgCode,jdbcType=VARCHAR} ORG_CODE, #{item.deptCode,jdbcType=VARCHAR} DEPT_CODE, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.agent,jdbcType=VARCHAR} AGENT, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, #{item.prodid,jdbcType=VARCHAR} PRODID, #{item.interfCheckResult,jdbcType=VARCHAR} INTERF_CHECK_RESULT, #{item.xbrlBackResult,jdbcType=VARCHAR} XBRL_BACK_RESULT, #{item.agencyCode,jdbcType=VARCHAR} AGENCY_CODE, #{item.fundAccPlace,jdbcType=VARCHAR} FUND_ACC_PLACE FROM dual
) TEMP)A

