select
 count(*)
from
  chb_investhold_info_check A
where
A.STATUS = 'E'
AND A.REGIST_BANK_CODE = #{registBankCode}
AND A.INDENTIFY_MARK = #{indentifyMark}
AND A.CCY = #{ccy}
AND A.HOLD_DATE = #{holdDate}
AND A.PRODID = #{prodid}
